effect.shader:
float r(vec2 p){
return fract(cos(p.x*42.98 + p.y*43.23) * 1127.53);
}
float n(vec2 p){
vec2 fn = floor(p);
vec2 sn = smoothstep(vec2(0.0), vec2(1.0), fract(p));
float h1 = mix(r(fn), r(fn + vec2(1.0,0.0)), sn.x);
float h2 = mix(r(fn + vec2(0.0,1.0)), r(fn + vec2(1.0)), sn.x);
return mix(h1, h2, sn.y);
}
float noiseFBM(vec2 p){
return n(p/32.0) * 0.58 +
n(p/16.0) * 0.20 +
n(p/8.0)  * 0.10 +
n(p/4.0)  * 0.05 +
n(p/2.0)  * 0.02 +
n(p)      * 0.0125;
}
vec3 backgroundTex(vec2 pos){
vec2 offset = vec2(0.0, bgSpeed * time);
vec3 color = vec3(1.0);
for(int i=0; i<3; ++i){
float w = abs(mod(float(i) * 0.666, 2.0) - 1.0);
vec3 a = texture2DCv(bgTex.texture, pos - 0.25 * offset + 0.5).rgb;
vec3 b = texture2DCv(bgTex.texture, pos - offset).rgb;
color += mix(a, b, w) * color * color;
}
return color * vec3(0.0666, 0.0266, 0.00333);
}
void main(){
vec2 res = acScreenSize;
vec2 fragCoord = acScreenNorm * res;
vec2 uv = acScreenNorm;
float t = progress * 1.2;
float val = noiseFBM(fragCoord * (noiseScale));
float m = smoothstep(t + feather, t - feather, val);
vec4 src = texture2DCv(inputImg.texture, uv);
vec4 c = mix(src, vec4(0.0), m);
float edge = step(c.a, 0.10);
vec3 heat = heatColor.rgb * (burnIntensity * noiseFBM(2000.0 * uv));
c.rgb = clamp(c.rgb + edge * heat, 0.0, 1.0);
if (useBackground) {
vec3 bg = backgroundTex(bgScale * uv);
c.rgb = c.rgb * step(0.01, c.a) + bg * step(c.a, 0.01);
} else {
c.rgb *= step(0.01, c.a);
}
gl_FragColor = c;
}
